import{_ as a,o as t,c as i,ae as o}from"./chunks/framework.Czhw_PXq.js";const u=JSON.parse('{"title":"ADR 030: High Coverage Standard for Domain Logic","description":"","frontmatter":{},"headers":[],"relativePath":"adr/030-high-coverage-standard.md","filePath":"adr/030-high-coverage-standard.md"}'),r={name:"adr/030-high-coverage-standard.md"};function n(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-030-high-coverage-standard-for-domain-logic" tabindex="-1">ADR 030: High Coverage Standard for Domain Logic <a class="header-anchor" href="#adr-030-high-coverage-standard-for-domain-logic" aria-label="Permalink to &quot;ADR 030: High Coverage Standard for Domain Logic&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>In the final phase of development, we identified that the core business logic (Domain Layer) and critical infrastructure adapters were under-tested (~64% global coverage). Given the critical nature of the application (Tender Analysis), we need to ensure high reliability for:</p><ol><li><strong>Validation Rules</strong>: Ensure all industry-specific rules are correctly applied.</li><li><strong>AI Integration</strong>: Ensure fallback mechanisms work when AI services fail.</li><li><strong>Authentication</strong>: Ensure user access is correctly controlled.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We decided to enforce a <strong>Strict High Coverage Standard</strong>:</p><ul><li><strong>100% Line Coverage for Domain Layer</strong>: All Entities, Value Objects, Domain Services, and Validation Rules must be fully tested.</li><li><strong>&gt;80% Global Line Coverage</strong>: The entire backend codebase must meet this threshold.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Confidence</strong>: We can refactor core logic with zero fear of breaking business rules.</li><li><strong>Bug Prevention</strong>: Edge cases in <code>ValidationRuleFactory</code> and <code>VectorSearchService</code> (e.g., empty embeddings, DB failures) were caught and fixed during test writing.</li><li><strong>Documentation</strong>: Tests serve as live documentation of the expected behavior.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Development Time</strong>: Writing comprehensive tests (especially mocking Turso and Genkit) requires significant effort.</li><li><strong>Build Time</strong>: CI/CD pipelines take slightly longer to run the full test suite.</li></ul><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to &quot;Implementation&quot;">​</a></h2><ul><li>Tests are implemented using <strong>Vitest</strong>.</li><li>External services (Turso, Google AI) are <strong>Mocked</strong> to ensure deterministic tests and avoid costs/latency.</li><li>Coverage thresholds are enforced via <code>vitest</code> configuration and pre-push hooks (Husky).</li></ul>',16)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
